// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.24;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Clones} from "@openzeppelin/contracts/proxy/Clones.sol";
import {SettlementWrapper} from "./SettlementWrapper.sol";
import {IRevenueRegistry} from "./interfaces/ITegata.sol";

/// @title TegataFactory
/// @notice Entry point for merchant onboarding and holder of the keeper role.
///         `registerMerchant` deploys a SettlementWrapper clone (EIP-1167) that becomes
///         the merchant's HSP `recipient` address, and registers the pair in the
///         RevenueRegistry. Owner (deployer) is the hackathon admin.
contract TegataFactory is Ownable {
    error ZeroAddress();

    /// @notice Emitted when a merchant registers and their wrapper is deployed.
    event MerchantRegistered(address indexed merchant, address indexed wrapper, address payoutAddress);
    /// @notice Emitted when a keeper is granted or revoked.
    event KeeperSet(address indexed keeper, bool enabled);

    /// @notice The RevenueRegistry all wrappers report to.
    IRevenueRegistry public immutable registry;
    /// @notice The LenderPool all wrappers repay into.
    address public immutable pool;
    /// @notice The settlement stablecoin wrappers receive (sandbox USDC on testnet).
    address public immutable stablecoin;
    /// @notice The SettlementWrapper implementation all clones delegate to.
    address public immutable wrapperImplementation;

    /// @notice account => is an authorized settlement keeper.
    mapping(address => bool) public isKeeper;

    constructor(IRevenueRegistry registry_, address pool_, address stablecoin_) Ownable(msg.sender) {
        if (address(registry_) == address(0) || pool_ == address(0) || stablecoin_ == address(0)) {
            revert ZeroAddress();
        }
        registry = registry_;
        pool = pool_;
        stablecoin = stablecoin_;
        wrapperImplementation = address(new SettlementWrapper());
    }

    /// @notice Registers the caller as a merchant and deploys their settlement wrapper.
    ///         The wrapper address is what the merchant sets as their HSP mandate
    ///         `recipient`. Reverts (in the registry) if already registered.
    /// @param payoutAddress Where the merchant's share of each settlement is sent.
    /// @return wrapper The merchant's freshly deployed SettlementWrapper clone.
    function registerMerchant(address payoutAddress) external returns (address wrapper) {
        if (payoutAddress == address(0)) revert ZeroAddress();
        wrapper = Clones.clone(wrapperImplementation);
        SettlementWrapper(wrapper)
            .initialize(msg.sender, payoutAddress, address(this), address(registry), pool, stablecoin);
        registry.registerMerchant(msg.sender, wrapper);
        emit MerchantRegistered(msg.sender, wrapper, payoutAddress);
    }

    /// @notice Grants or revokes the settlement keeper role. Owner-only.
    /// @param keeper The keeper account (our off-chain HSP-verifying service).
    /// @param enabled True to grant, false to revoke.
    function setKeeper(address keeper, bool enabled) external onlyOwner {
        if (keeper == address(0)) revert ZeroAddress();
        isKeeper[keeper] = enabled;
        emit KeeperSet(keeper, enabled);
    }
}

