import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Initializable} from "@openzeppelin/contracts/proxy/utils/Initializable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {ITegataFactory, ILenderPool, IRevenueRegistry} from "./interfaces/ITegata.sol";

/// @title SettlementWrapper
/// @notice Per-merchant receiving address for HSP settlements, deployed as an EIP-1167
///         clone by TegataFactory. HSP settlement is a plain ERC-20 `transfer()` to this
///         address and MUST NOT execute logic (HSP rejects settlement txs with more than
///         one Transfer log), so funds simply accumulate here. The keeper — after
///         verifying the payment off-chain via the HSP API — calls `distribute()` in a
///         follow-up tx, which splits the settlement: repayment slice to the LenderPool,
///         remainder to the merchant's payout address, and records the settlement in the
///         RevenueRegistry for credit scoring.
/// @dev    No other function moves funds; there is deliberately no rescue/sweep so the
///         keeper's split is the only exit path. OZ ReentrancyGuard is safe in clones:
///         its status slot starts at 0, which the guard treats as not-entered.
contract SettlementWrapper is Initializable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    error NotKeeper();
    error InsufficientSettledBalance(uint256 requested, uint256 balance);
    error ZeroAmount();

    /// @notice Emitted on every keeper-executed settlement split.
    event Distributed(
        address indexed merchant,
        uint256 indexed paymentId,
        uint256 grossAmount,
        uint256 repaidAmount,
        uint256 payoutAmount
    );

    uint256 internal constant BPS = 10_000;

    /// @notice The merchant's identity address (registered in the registry).
    address public merchant;
    /// @notice Where the merchant's share of each settlement is sent.
    address public payoutAddress;
    /// @notice Factory holding the keeper role.
    ITegataFactory public factory;
    /// @notice Registry that records verified settlements.
    IRevenueRegistry public registry;
    /// @notice Pool that receives repayment slices.
    ILenderPool public pool;
    /// @notice The settlement stablecoin (HSP sandbox USDC on testnet).
    IERC20 public stablecoin;

    constructor() {
        _disableInitializers();
    }

    /// @notice Initializes a freshly deployed clone. Called by the factory in the same
    ///         tx as the clone deployment.
    /// @param merchant_ Merchant identity address.
    /// @param payoutAddress_ Destination for the merchant's settlement share.
    /// @param factory_ TegataFactory (keeper role source).
    /// @param registry_ RevenueRegistry.
    /// @param pool_ LenderPool.
    /// @param stablecoin_ Settlement token.
    function initialize(
        address merchant_,
        address payoutAddress_,
        address factory_,
        address registry_,
        address pool_,
        address stablecoin_
    ) external initializer {
        merchant = merchant_;
        payoutAddress = payoutAddress_;
        factory = ITegataFactory(factory_);
        registry = IRevenueRegistry(registry_);
        pool = ILenderPool(pool_);
        stablecoin = IERC20(stablecoin_);
    }

    /// @notice Splits a verified HSP settlement of `amount` between loan repayment and
    ///         the merchant payout, and records it in the registry. Keeper-only.
    /// @dev Split rules: no active loan → 100% to merchant; otherwise
    ///      slice = amount * repaymentBps / 10_000, capped at the remaining debt, with
    ///      the remainder to the merchant. Reverts if `amount` exceeds the wrapper's
    ///      current balance (keeper must only distribute verified, settled funds).
    /// @param paymentId HSP payment id (uniqueness enforced by the registry).
    /// @param amount Gross settlement amount to distribute.
    function distribute(uint256 paymentId, uint256 amount) external nonReentrant {
        if (!factory.isKeeper(msg.sender)) revert NotKeeper();
        if (amount == 0) revert ZeroAmount();
        uint256 balance = stablecoin.balanceOf(address(this));
        if (amount > balance) revert InsufficientSettledBalance(amount, balance);

        uint256 slice = 0;
        uint256 debt = pool.outstandingDebt(merchant);
        if (debt > 0) {
            slice = (amount * pool.repaymentBps(merchant)) / BPS;
            if (slice > debt) slice = debt;
            if (slice > 0) {
                stablecoin.forceApprove(address(pool), slice);
                pool.repay(merchant, slice);
            }
        }

        uint256 remainder = amount - slice;
        if (remainder > 0) {
            stablecoin.safeTransfer(payoutAddress, remainder);
        }

        registry.recordSettlement(merchant, paymentId, amount);
        emit Distributed(merchant, paymentId, amount, slice, remainder);
    }
}

