pragma solidity ^0.8.24;

/// @title ITegataFactory
/// @notice Minimal surface of the factory needed by other Tegata contracts.
interface ITegataFactory {
    /// @notice Whether `account` is an authorized settlement keeper.
    function isKeeper(address account) external view returns (bool);
}

/// @title IRevenueRegistry
/// @notice Minimal surface of the revenue registry needed by other Tegata contracts.
interface IRevenueRegistry {
    /// @notice Registers a merchant and their settlement wrapper. Factory-only.
    function registerMerchant(address merchant, address wrapper) external;

    /// @notice Records a verified HSP settlement. Wrapper-only.
    function recordSettlement(address merchant, uint256 paymentId, uint256 amount) external;

    /// @notice Sum of `merchant`'s settlements within the last `window` seconds.
    function trailingRevenue(address merchant, uint256 window) external view returns (uint256);

    /// @notice The settlement wrapper registered for `merchant` (zero if unregistered).
    function wrapperOf(address merchant) external view returns (address);
}

/// @title ILenderPool
/// @notice Minimal surface of the lender pool needed by the settlement wrapper.
interface ILenderPool {
    /// @notice Current debt (principal + fee, minus repayments) of `merchant`.
    function outstandingDebt(address merchant) external view returns (uint256);

    /// @notice Basis points of each settlement deducted for repayment.
    function repaymentBps(address merchant) external view returns (uint256);

    /// @notice Repays `amount` of `merchant`'s debt, pulling USDC from the caller.
    function repay(address merchant, uint256 amount) external;
}
